#define BETTER_APPROX
#define THICKNESS 0.01

// Put your function here
float f(float x)
{
    int s = int(mod(iTime*0.5, 4.));
    switch(s)
    {
    case 0:
        return sin(x*5.+iTime)*0.5;
        break;
    case 1:
         x -= 0.3;
        return -x*x-x*x*x;
        break;
    case 2:
        x += 0.5;
        return 3.*x*x-2.*x*x*x-0.5;
        break;
    case 3:
        return (sin(x*5.)+cos(x*10.+iTime))*0.25;
        break;
    }
}

float graph(vec2 p)
{
    float f = f(p.x);
    return abs(p.y-f)
    #ifdef BETTER_APPROX
    -abs(dFdx(f))
    #endif
    ;
}

float map(vec2 uv)
{
    return graph(uv);
}

vec3 colorSdf(vec2 uv, vec4 m, float px)
{
    #define PERIOD 200.
    #define STR 0.2
    #define STROKE_WIDTH 0.005
    #define MOUSE_WIDTH 0.005
    float d = map(uv);
    float md = map(m.xy);
    vec3 col = mix(vec3(0.094,0.494,0.988), vec3(1.000,0.082,0.980), sign(d)*0.5+0.5);
    col *= smoothstep(-px*PERIOD, px*PERIOD, cos(d*PERIOD))*STR+1.-STR;
    col = mix(col, vec3(1), smoothstep(STROKE_WIDTH+px, STROKE_WIDTH-px, abs(d)));
    if(m.z > 0.)
    {
        float mdc = smoothstep(px, -px, min(abs(distance(m.xy, uv)-md+MOUSE_WIDTH)-MOUSE_WIDTH, distance(m.xy, uv)-MOUSE_WIDTH*2.));
        col = mix(col, vec3(1.000,0.875,0.000), mdc);
    }
    col /= d+1.;
    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord*2.-iResolution.xy)/iResolution.y;
    vec4 m = (iMouse*2.-iResolution.xyxy)/iResolution.y;
    float px = 2./iResolution.y;

    float g = graph(uv);
    float fw = fwidth(g);
    vec3 col = vec3(smoothstep(THICKNESS+fw, THICKNESS-fw, g));

    // Output to screen
    fragColor = vec4(mix(col, colorSdf(uv, m, px), clamp(iMouse.z, 0., 1.)),1.0);
}







